#include <cctype>
#include <iostream>

int main()
{
    char c{};
    std::cin >> c;

    std::cout << std::boolalpha;
    std::cout << "Character: " << c << '\n';
    std::cout << "Code: " << static_cast<int>(c) << '\n';
    std::cout << "Uppercase: " << static_cast<char>(std::toupper(c)) << '\n';
    std::cout << "Is a letter: " << (std::isalpha(c) != 0) << '\n';
    std::cout << "Is a digit: " << (std::isdigit(c) != 0) << '\n';
    return 0;
}
